parameters.jsonBody:
={
  "query": "query ($id: [ID!]!) { items(ids: $id) { name column_values { id type text value } } }",
  "variables": { "id": [{{ JSON.stringify(String($json.body.pulseId)) }}] }
}

parameters.jsCode:
const item = $input.first().json.data?.items?.[0];
if (!item) throw new Error('item not found');
const col = (id) => item.column_values.find(c => c.id === id);
const text = (c) => c?.text?.trim() || '';
const pulseId = $('Webhook: /marketa-revise').first().json.body.pulseId;
const draft = text(col('long_text_mm3gj0s8'));
const notes = text(col('long_text_mm3g2bp9'));
if (!draft) throw new Error('no existing draft');
if (!notes) throw new Error('no edit notes');
return [{ json: { pulseId: String(pulseId), title: item.name, draft, notes } }];

parameters.jsonBody:
={
  "model": "claude-opus-4-7",
  "max_tokens": 6000,
  "system": "You are Marketa revising a draft per reviewer feedback. Apply the requested changes precisely without rewriting unaffected sections. Preserve voice (confident, plain-spoken, technical). Banned vocabulary: leverage, synergise, best-in-class, unlock potential, drive transformation. No AI-tell phrases. Short paragraphs.",
  "messages": [{
    "role": "user",
    "content": {{ JSON.stringify('Title: ' + $json.title + '\n\nCurrent draft:\n' + $json.draft + '\n\nReviewer edit notes:\n' + $json.notes + '\n\nReturn the full revised draft in markdown. No preamble.') }}
  }]
}

parameters.jsCode:
const revised = $input.first().json.content?.[0]?.text || '';
const pulseId = $('Normalize item').first().json.pulseId;
return [{ json: { pulseId, revised } }];

